import React, { useState, useRef, useEffect } from 'react';
import styles from './rag-react.module.css'; // same module as Home.js
import { callApi } from '../api/client';

export default function Rag() {
  const [queryInput, setQueryInput] = useState('');
  const [messages, setMessages] = useState([]); // { sender:'user'|'bot', text }
  const containerRef = useRef(null);
  const inputRef = useRef(null);

  // auto-scroll on new message
  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages]);

  const submitQuery = async () => {
    const prompt = queryInput.trim();
    if (!prompt) return;

    // push user message
    setMessages(m => [...m, { sender: 'user', text: prompt }]);
    setQueryInput('');
    inputRef.current.focus();

    try {
      const { answer } = await callApi('rag', 'POST', { query: prompt });
      setMessages(m => [...m, { sender: 'bot', text: answer }]);
    } catch (err) {
      console.error(err);
      setMessages(m => [...m, { sender: 'bot', text: 'Error fetching response.' }]);
    }
  };

  const handleKeyDown = e => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      submitQuery();
    }
  };

  return (
    <div className={styles.autoML}>
      <div className={styles.container}>
        {/* Chat History */}
        <div className={styles.chatContainer} ref={containerRef}>
          {messages.map((m, i) => (
            <div
              key={i}
              className={`${styles.chatBubble} ${
                m.sender === 'user' ? styles.userBubble : styles.botBubble
              }`}
            >
              {m.text}
            </div>
          ))}
        </div>

        {/* Input Area */}
        <form
          onSubmit={e => {
            e.preventDefault();
            submitQuery();
          }}
          className={styles.inputArea}
        >
          <div className={styles.inputWrapper}>
            <input
              type="text"
              ref={inputRef}
              className={styles.inputField || undefined}
              placeholder="Type your message..."
              value={queryInput}
              onChange={e => setQueryInput(e.target.value)}
              onKeyDown={handleKeyDown}
              autoComplete="off"
            />
            <div className={styles.inputIcons}>
              {/* reuse your iconButton or swap to a send icon */}
              <button
                type="button"
                onClick={submitQuery}
                className={styles.iconButton}
                disabled={!queryInput.trim()}
                title="Send"
              >
                ➤
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
}
